INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29h-2017-q11','exam-sg','ISMS・教育と認識','standard','single_choice','【2017年度 平成29年春期 午前 問11】JIS Q 27001:2014において，組織の管理下で働く人々が認識をもたなければならないとされている「ISMSの有効性に対する自らの貢献」及び「ISMS要求事項に適合しないことの意味」と，もう一つはどれか。','[{"id":"a","text":"情報セキュリティ適用宣言"},{"id":"b","text":"情報セキュリティ方針"},{"id":"c","text":"情報セキュリティ内部監査結果"},{"id":"d","text":"情報セキュリティリスク対応計画"}]','"c"','正解はウ。組織の人々は，自らの貢献や要求事項に適合しない場合の影響に加え，ISMSに関する内部監査結果などを認識する必要がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q12','exam-sg','脆弱性情報・JVN','standard','single_choice','【2017年度 平成29年春期 午前 問12】情報セキュリティ管理における情報収集源の一つであるJVNが主として提供する情報はどれか。','[{"id":"a","text":"工業製品などの技術評価，製品事故情報及び品質情報"},{"id":"b","text":"国家や重要インフラに影響を及ぼす情報セキュリティ事件・事故とその対応情報"},{"id":"c","text":"ソフトウェアなどの脆弱性関連情報や対策情報"},{"id":"d","text":"日本国内で発生した情報セキュリティインシデントの相談窓口に関する情報"}]','"c"','正解はウ。JVNはソフトウェア等の脆弱性情報と，それに対する対策情報を提供する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q13','exam-sg','侵入検知・NIDS','standard','single_choice','【2017年度 平成29年春期 午前 問13】NIDS（ネットワーク型IDS）を導入する目的はどれか。','[{"id":"a","text":"管理下のネットワークへの侵入の試みを検知し，管理者に通知する。"},{"id":"b","text":"実際にネットワーク経由でWebサイトを攻撃し，侵入できるかを検証する。"},{"id":"c","text":"ネットワークからの攻撃を防御できないときの損失の大きさを判定する。"},{"id":"d","text":"ネットワーク接続サーバに格納されたファイルが改ざんされたかどうかを判定する。"}]','"a"','正解はア。NIDSはネットワーク上の通信を監視して，不正な侵入やその兆候を検知・通知する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q14','exam-sg','内部不正・ログ監査','standard','single_choice','【2017年度 平成29年春期 午前 問14】内部不正による重要なデータ漏えいの可能性を早期に発見するために有効な対策はどれか。','[{"id":"a","text":"アクセスログの定期的な確認と解析"},{"id":"b","text":"ウイルス対策ソフトの導入"},{"id":"c","text":"重要なデータのバックアップ"},{"id":"d","text":"ノートPCのHDD暗号化"}]','"a"','正解はア。アクセスログを定期的に点検・分析すると，不自然な閲覧や持ち出しの兆候を発見しやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q15','exam-sg','デジタルフォレンジックス','standard','single_choice','【2017年度 平成29年春期 午前 問15】デジタルフォレンジックスの説明として，適切なものはどれか。','[{"id":"a","text":"運用基準に従ってメールサーバを通過する送受信メールをフィルタリングすること"},{"id":"b","text":"外部からの攻撃や不正アクセスからサーバを防御すること"},{"id":"c","text":"記憶媒体の廃棄前に任意のデータ列で上書きし，復元を困難にすること"},{"id":"d","text":"コンピュータ犯罪などの原因究明に必要なデータを，法的な証拠性を確保できるよう保全・収集・分析すること"}]','"d"','正解はエ。デジタルフォレンジックスは，調査に必要な電子データを適切に保全し，証拠として分析する活動である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q16','exam-sg','パスワード攻撃対策','standard','single_choice','【2017年度 平成29年春期 午前 問16】サーバへのログインに用いるパスワードを不正に取得しようとする攻撃と，その対策の組合せのうち，適切なものはどれか。','[{"id":"a","text":"辞書攻撃：推測されにくいパスワードを設定する／スニッフィング：パスワードを暗号化して送信する／ブルートフォース攻撃：ログイン試行回数を制限する"},{"id":"b","text":"辞書攻撃：推測されにくいパスワードを設定する／スニッフィング：ログイン試行回数を制限する／ブルートフォース攻撃：パスワードを暗号化して送信する"},{"id":"c","text":"辞書攻撃：パスワードを暗号化して送信する／スニッフィング：ログイン試行回数を制限する／ブルートフォース攻撃：推測されにくいパスワードを設定する"},{"id":"d","text":"辞書攻撃：ログイン試行回数を制限する／スニッフィング：推測されにくいパスワードを設定する／ブルートフォース攻撃：パスワードを暗号化して送信する"}]','"a"','正解はア。辞書攻撃には推測されにくいパスワード，盗聴には暗号化通信，総当たり攻撃には試行回数制限が有効である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q17','exam-sg','ネットワーク分離・DMZ','standard','single_choice','【2017年度 平成29年春期 午前 問17】外部セグメント，DMZ，内部セグメントに分割されたネットワークで，Webサーバと重要データを持つデータベースサーバを公開サービスに用いる。重要データをインターネットから保護する設置方法として最も適切なものはどれか。','[{"id":"a","text":"WebサーバとデータベースサーバをDMZに設置する。"},{"id":"b","text":"Webサーバとデータベースサーバを内部セグメントに設置する。"},{"id":"c","text":"WebサーバをDMZに，データベースサーバを内部セグメントに設置する。"},{"id":"d","text":"Webサーバを外部セグメントに，データベースサーバをDMZに設置する。"}]','"c"','正解はウ。外部公開するWebサーバはDMZに置き，重要データを保持するDBサーバは内部ネットワークに分離する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q18','exam-sg','認証・二要素認証','standard','single_choice','【2017年度 平成29年春期 午前 問18】二要素認証に該当する組合せはどれか。','[{"id":"a","text":"クライアント証明書とハードウェアトークン"},{"id":"b","text":"静脈認証と指紋認証"},{"id":"c","text":"パスワード認証と静脈認証"},{"id":"d","text":"パスワード認証と秘密の質問の答え"}]','"c"','正解はウ。パスワードは知識要素，静脈認証は生体要素なので，異なる二つの要素を組み合わせている。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q19','exam-sg','電子証明書・電子署名','standard','single_choice','【2017年度 平成29年春期 午前 問19】二者間で商取引のメッセージを送受信するとき，送信者のディジタル証明書を使用して行えることはどれか。','[{"id":"a","text":"受信者が暗号文を送信者の公開鍵で復号し，購入しようとした商品名が正しいことを確認する。"},{"id":"b","text":"受信者が暗号文を送信者の公開鍵で復号し，メッセージの盗聴を検知する。"},{"id":"c","text":"受信者がディジタル署名を検証し，メッセージがその送信者からのものであることを確認する。"},{"id":"d","text":"送信者がメッセージにディジタル証明書を添付し，メッセージの盗聴を防止する。"}]','"c"','正解はウ。証明書で検証した公開鍵を用いて電子署名を検証することで，送信者の確認や改ざん検知に役立つ。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q20','exam-sg','ハッシュ関数','standard','single_choice','【2017年度 平成29年春期 午前 問20】ディジタル署名などに用いるハッシュ関数の特徴はどれか。','[{"id":"a","text":"同じメッセージダイジェストを出力する二つの異なるメッセージは容易に求められる。"},{"id":"b","text":"メッセージが異なっていても，メッセージダイジェストは全て同じである。"},{"id":"c","text":"メッセージダイジェストから元のメッセージを復元することは困難である。"},{"id":"d","text":"メッセージダイジェストの長さはメッセージの長さによって異なる。"}]','"c"','正解はウ。暗号学的ハッシュ関数は固定長のダイジェストを生成し，ダイジェストから元のメッセージを復元することは困難である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja');
